insert into public.training_modules (id, skill_id, title, description, difficulty, estimated_mins, xp_reward, config, is_active, created_at) values
  ('10000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'OSHA Basics: Workplace Safety', 'Learn the essentials of OSHA compliance and how to identify workplace hazards.', 2, 15, 100, '{"type":"micro_drill","nodes":{"start":{"text":"What is the first step in addressing a reported safety hazard?","options":[{"label":"Investigate immediately","next_node":"correct","impact":{"trust":5,"compliance":10,"budget":0},"explanation":"Prompt investigation is required by OSHA."},{"label":"Wait for a pattern to emerge","next_node":"incorrect","impact":{"trust":-5,"compliance":-10,"budget":0},"explanation":"Delays can result in non-compliance."}]}},"initial_node":"start"}', true, now()),
  ('10000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', 'Building an Inclusive Culture', 'Strategies and legal requirements for fostering diversity and inclusion.', 3, 20, 120, '{"type":"micro_drill","nodes":{"start":{"text":"A candidate requests a religious accommodation. What should you do?","options":[{"label":"Deny the request","next_node":"incorrect","impact":{"trust":-10,"compliance":-20,"budget":0},"explanation":"Title VII requires reasonable accommodation."},{"label":"Engage in interactive process","next_node":"correct","impact":{"trust":10,"compliance":20,"budget":0},"explanation":"Best practice and legal requirement."}]}},"initial_node":"start"}', true, now()),
  ('10000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000004', 'Preventing Workplace Harassment', 'Recognize, prevent, and respond to harassment in the workplace.', 2, 15, 100, '{"type":"micro_drill","nodes":{"start":{"text":"An employee reports harassment. What is your first obligation?","options":[{"label":"Investigate promptly","next_node":"correct","impact":{"trust":10,"compliance":20,"budget":0},"explanation":"Prompt investigation is required by EEOC guidance."},{"label":"Ignore unless repeated","next_node":"incorrect","impact":{"trust":-10,"compliance":-20,"budget":0},"explanation":"All complaints must be taken seriously."}]}},"initial_node":"start"}', true, now()),
  ('10000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000003', 'FMLA: Managing Leave Requests', 'How to handle employee leave under the Family and Medical Leave Act.', 3, 20, 120, '{"type":"micro_drill","nodes":{"start":{"text":"An employee requests FMLA leave. What documentation do you need?","options":[{"label":"Medical certification","next_node":"correct","impact":{"trust":5,"compliance":10,"budget":0},"explanation":"FMLA requires medical certification for leave."},{"label":"No documentation needed","next_node":"incorrect","impact":{"trust":-5,"compliance":-10,"budget":0},"explanation":"Proper documentation is required for compliance."}]}},"initial_node":"start"}', true, now());
